create extension if not exists pgcrypto;
create table if not exists public.dr_creator_profiles (user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'Creator',creator_type text not null default 'writer',bio text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.dr_writer_manuscripts (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null default 'Untitled manuscript',deck text not null default '',body text not null default '',genre text not null default 'FANTASY',status text not null default 'draft' check(status in('draft','submitted','ready','published')),submitted_at timestamptz,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists dr_writer_manuscripts_user_status_idx on public.dr_writer_manuscripts(user_id,status,updated_at desc);
alter table public.dr_creator_profiles enable row level security; alter table public.dr_writer_manuscripts enable row level security;
drop policy if exists "creator own profile select" on public.dr_creator_profiles; create policy "creator own profile select" on public.dr_creator_profiles for select using(auth.uid()=user_id);
drop policy if exists "creator own profile insert" on public.dr_creator_profiles; create policy "creator own profile insert" on public.dr_creator_profiles for insert with check(auth.uid()=user_id);
drop policy if exists "creator own profile update" on public.dr_creator_profiles; create policy "creator own profile update" on public.dr_creator_profiles for update using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "writer own manuscript select" on public.dr_writer_manuscripts; create policy "writer own manuscript select" on public.dr_writer_manuscripts for select using(auth.uid()=user_id);
drop policy if exists "writer own manuscript insert" on public.dr_writer_manuscripts; create policy "writer own manuscript insert" on public.dr_writer_manuscripts for insert with check(auth.uid()=user_id);
drop policy if exists "writer own manuscript update" on public.dr_writer_manuscripts; create policy "writer own manuscript update" on public.dr_writer_manuscripts for update using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "writer own manuscript delete" on public.dr_writer_manuscripts; create policy "writer own manuscript delete" on public.dr_writer_manuscripts for delete using(auth.uid()=user_id);
create or replace function public.dr_handle_new_creator() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.dr_creator_profiles(user_id,display_name,creator_type) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),split_part(new.email,'@',1),'Creator'),coalesce(nullif(new.raw_user_meta_data->>'creator_type',''),'writer')) on conflict(user_id) do nothing; return new; end; $$;
drop trigger if exists dr_on_auth_user_created on auth.users; create trigger dr_on_auth_user_created after insert on auth.users for each row execute procedure public.dr_handle_new_creator();
create or replace function public.dr_touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end; $$;
drop trigger if exists dr_touch_manuscript on public.dr_writer_manuscripts; create trigger dr_touch_manuscript before update on public.dr_writer_manuscripts for each row execute procedure public.dr_touch_updated_at();
